import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta,
            Grade grade, Integer weight, Kind kind, Integer verge, Integer thrust, Integer drift, Integer momentum, Integer force, Integer sway, Integer torque, Integer pivot, Integer blend, Integer flux, Integer crest, Integer swing, Integer haul, String phase, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout, Integer influence, Integer brace, List<String> regions, Integer reach, Integer gust, Integer coil,
            List<PatronView> allies, int allyCount, Integer synergy, Integer combined, Integer score, int noteSum, Integer quality, Integer adjusted, String band, Integer scaled, Integer thrum, Integer spool, String drag, Integer lift, Integer norm, boolean outlier, State state) {
        static PersonView of(Person p, Map<Long, Integer> ranks, Integer medianScaled, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.getDelta(), p.getEpsilon(), p.getZeta(),
                    p.getGrade(), p.getWeight(), p.getKind(), p.getVerge(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getForce(), p.getSway(), p.getTorque(), p.getPivot(), p.getBlend(), p.getFlux(), p.getCrest(), p.getSwing(), p.getHaul(), p.getPhase(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout(),
                    p.getInfluence(), p.getBrace(), p.getRegions(), p.getReach(), p.getGust(), p.getCoil(),
                    p.getAllies().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getAllies().size(), p.getSynergy(), p.getCombined(), p.getScore(), p.getNoteSum(), p.getQuality(), p.getAdjusted(), p.getBand(), p.getScaled(), p.getThrum(), p.getSpool(), p.getDrag(), p.getLift(),
                    PersonController.norm(p.getScaled(), medianScaled),
                    PersonController.outlier(PersonController.norm(p.getScaled(), medianScaled)), p.getState());
        }
    }

 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the average of the
 * patrons' effective, rounded down (zero without patrons). "Influence" is effective plus clout. "Brace" is influence plus two times force.
 * A person may belong to any number of "regions": short codes typed in, like N1 or S2. A region's
 * "multiplier" comes from its first letter: N is 2, S is 3, any other is 1. "Reach" is the sum, over the
 * person's regions, of momentum times that region's multiplier. "Gust" is reach plus two times torque. "Coil" is gust minus momentum. A person may follow any number of other people on
 * the list, without being followed back; their "allies" are the people they follow. "Synergy" is the
 * allies' thrust added together (zero without allies). "Combined" is influence plus synergy.
 * A person may have a whole-number "score" (absent until given); their "note sum" is the score (zero
 * without one) and their "quality" is the score (absent without one). A person has a workflow "state",
 * starting at DRAFT and moved forward to REVIEW and then FINAL; a FINAL person may be reopened to REWORK
    }

    /** Lift is blend times the drag's multiplier: L0 0, L1 1, L2 2, L3 3; absent with blend. */
    public Integer getLift() {
        Integer blend = getBlend();
        if (blend == null) {
            return null;
        }
        int multiplier = switch (getDrag()) {
            case "L3" -> 3;
            case "L2" -> 2;
            case "L1" -> 1;
            default -> 0;
        };
        return blend * multiplier;
    }

    /** Band classifies adjusted: E below 0, D up to 99, C up to 249, B up to 499, A from 500; absent with adjusted. */
    public String getBand() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        return adjusted < 0 ? "E" : adjusted <= 99 ? "D" : adjusted <= 249 ? "C" : adjusted <= 499 ? "B" : "A";
    }

    /** Scaled is adjusted times the band's multiplier: A 4, B 3, C 2, D 1, E 0; absent with adjusted. */
    public Integer getScaled() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        int multiplier = switch (getBand()) {
            case "A" -> 4;
            case "B" -> 3;
            case "C" -> 2;
            case "D" -> 1;
            default -> 0;
        };
        return adjusted * multiplier;
    }

    /** Thrum is scaled plus two times torque; absent while either is absent. */
    public Integer getThrum() {
        Integer scaled = getScaled();
        Integer torque = getTorque();
        return scaled == null || torque == null ? null : scaled + 2 * torque;
    }

    /** Spool is thrum minus blend; absent while either is absent. */
    public Integer getSpool() {
        Integer thrum = getThrum();
        Integer blend = getBlend();
        return thrum == null || blend == null ? null : thrum - blend;
    }

    /** Gust is reach plus two times torque; absent while either is absent. */
    public Integer getGust() {
        Integer reach = getReach();
        Integer torque = getTorque();
        return reach == null || torque == null ? null : reach + 2 * torque;
    }

  noteSum: number;
  quality: number | null;
  adjusted: number | null;
  band: string | null;
  scaled: number | null;
  thrum: number | null;
  spool: number | null;
  drag: string | null;
  lift: number | null;
  norm: number | null;
  outlier: boolean;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
// Their thrum is their scaled plus two times their torque ("n/a" while either is "n/a").
// The sheet's max thrum is the name of the person with the highest thrum, ties going to the name that
// comes first alphabetically ("n/a" when nobody has a thrum).
// Their spool is their thrum minus their blend ("n/a" while either is "n/a").
// Their drag classifies blend: L0 below zero, L1 up to 49, L2 up to 149, L3 from 150 ("n/a" while blend is).
// Their lift is their blend times their drag's multiplier: L0 0, L1 1, L2 2, L3 3 ("n/a" while blend is).
// Their norm is their scaled minus the median scaled of everyone on the sheet whose scaled can be
// worked out; for an even count, the lower of the two middle values ("n/a" while their scaled is "n/a").
// They are an outlier ("yes") when their norm is more than 100 away from zero in either direction, and
// otherwise "no" (also "no" while their norm is "n/a").
// The sheet's outlier count is how many of its people are outliers.
// The sheet's final total is the sum of the scaled of its people whose state is FINAL, counting
// "n/a" as zero.
// The sheet's band counts show how many of its people are in each band, A through E (zero when none
// are); people whose band is "n/a" are not counted.
          <th scope="col">Note sum</th>
          <th scope="col">Quality</th>
          <th scope="col">Adjusted</th>
          <th scope="col">Band</th>
          <th scope="col">Scaled</th>
          <th scope="col">Thrum</th>
          <th scope="col">Spool</th>
          <th scope="col">Drag</th>
          <th scope="col">Lift</th>
          <th scope="col">Norm</th>
          <th scope="col">Outlier</th>
          <th scope="col">Rank</th>
          <th scope="col">Percentile</th>
          <th scope="col">Set alpha</th>
          <th scope="col">Set beta</th>
          <th scope="col">Set gamma</th>
          <th scope="col">Set delta</th>
          <th scope="col">Set epsilon</th>
          <th scope="col">Set zeta</th>
          <th scope="col">Set grade</th>
          <th scope="col">Set kind</th>
            <td data-testid="concept-band">{{ p.band ?? 'n/a' }}</td>
            <td data-testid="concept-scaled">{{ p.scaled ?? 'n/a' }}</td>
            <td data-testid="concept-thrum">{{ p.thrum ?? 'n/a' }}</td>
            <td data-testid="concept-spool">{{ p.spool ?? 'n/a' }}</td>
            <td data-testid="concept-drag">{{ p.drag ?? 'n/a' }}</td>
            <td data-testid="concept-lift">{{ p.lift ?? 'n/a' }}</td>
            <td data-testid="concept-norm">{{ p.norm ?? 'n/a' }}</td>
            <td data-testid="concept-outlier">{{ p.outlier ? 'yes' : 'no' }}</td>
            <td data-testid="concept-rank">{{ p.rank ?? 'n/a' }}</td>
            <td data-testid="concept-percentile">{{ p.percentile ?? 'n/a' }}</td>
            <td>
              <form (submit)="$event.preventDefault(); setAlpha(p, alphaInput.value)">
                <label class="visually-hidden" [for]="'person-alpha-edit-' + p.id">
                  Alpha for {{ p.name }}
                </label>
